!function(){"use strict";app.directive("btnDatoAdicionalArticuloFactElect",(function(modalService,nombreModalFactElect){return{restrict:"A",scope:{entity:"=",resultModalAdicional:"&",datosAdicionales:"=",historyDatosAdicionales:"="},link:function(scope,element,attrs){element.on("click",(async function(){if(console.log(scope),!Number.isInteger(scope.entity.cantidad))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"El valor de la cantidad del artículo tiene que ser un número entero!"});let{fileCtrl:fileCtrl,controller:controller,template:template}=nombreModalFactElect.DATO_ADICIONAL_ARTICULO,ctrl=(await import(fileCtrl))[controller],modalRef;modalService.openModalCustom({controller:ctrl,template:template,size:"lg",params:{entity:scope.entity,datosAdicionales:scope.datosAdicionales||[],historyDatosAdicionales:scope.historyDatosAdicionales||[]},isRenderRazorPartial:!0}).result.then(result=>{scope.resultModalAdicional({result:result})})}))}}}))}(window.angular);